"""Full-molecule isotope distributions via iterated exact convolution."""

import re

# element -> list of (integer mass, abundance)
ISOTOPES = {
    "C":  [(12, 0.9893), (13, 0.0107)],
    "H":  [(1, 0.999885), (2, 0.000115)],
    "N":  [(14, 0.99636), (15, 0.00364)],
    "O":  [(16, 0.99757), (17, 0.00038), (18, 0.00205)],
    "P":  [(31, 1.0)],
}

_FORMULA_RE = re.compile(r"([A-Z][a-z]?)(\d*)")


def _parse_formula(formula):
    counts = {}
    for el, num in _FORMULA_RE.findall(formula):
        if not el:
            continue
        if el not in ISOTOPES:
            raise ValueError(f"Unknown element: {el}")
        counts[el] = counts.get(el, 0) + (int(num) if num else 1)
    if not counts:
        raise ValueError(f"Cannot parse formula: {formula!r}")
    return counts


def _convolve(a, b):
    out = [0.0] * (len(a) + len(b) - 1)
    for i, pa in enumerate(a):
        if pa == 0.0:
            continue
        for j, pb in enumerate(b):
            out[i + j] += pa * pb
    return out


def _element_dist(element, n):
    # distribution over integer mass shifts for one atom
    base_mass = ISOTOPES[element][0][0]
    single = [0.0] * (ISOTOPES[element][-1][0] - base_mass + 1)
    for mass, ab in ISOTOPES[element]:
        single[mass - base_mass] += ab
    # repeated convolution for n atoms
    dist = [1.0]
    for _ in range(n):
        dist = _convolve(dist, single)
    return dist


def isotopes(formula):
    """Return isotope pattern intensities normalized to base peak = 100.

    Index i of the result corresponds to nominal mass M+i.
    """
    total = [1.0]
    for el, n in _parse_formula(formula).items():
        total = _convolve(total, _element_dist(el, n))
    peak = max(total)
    return [x / peak * 100.0 for x in total]

