from isotopes import isotopes


def rel(dist):
    return dist[1] / dist[0] * 100.0


def test_c60():
    d = isotopes("C60")
    assert abs(d[1] / d[0] * 100 - 64.9) < 0.3


def test_atp():
    d = isotopes("C10H16N5O13P3")
    assert abs(d[1] / d[0] * 100 - 13.3) < 0.3


def test_co2_m2():
    d = isotopes("CO2")
    r = d[2] / d[0] * 100
    assert 0.35 <= r <= 0.55
